// 1.0.0: UI smoke test. Needs npm install --no-save playwright and a Chromium executable.
const fs=require('fs'),http=require('http'),path=require('path');
const {chromium}=require('playwright');
const root=path.join(__dirname,'..','renderer');
const out=path.join(__dirname,'artifacts');fs.mkdirSync(out,{recursive:true});
const server=http.createServer((req,res)=>{let p=path.join(root,decodeURIComponent(req.url.split('?')[0]));if(req.url==='/')p=path.join(root,'index.html');
 if(!p.startsWith(root)||!fs.existsSync(p)){res.writeHead(404);res.end();return;}
 res.setHeader('Content-Type',({'.js':'text/javascript','.css':'text/css','.html':'text/html','.svg':'image/svg+xml','.png':'image/png'})[path.extname(p)]||'application/octet-stream');fs.createReadStream(p).pipe(res);});
(async()=>{await new Promise(r=>server.listen(8756,'127.0.0.1',r));
 const browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH || 'chromium',headless:true,args:['--no-sandbox','--enable-unsafe-swiftshader','--autoplay-policy=no-user-gesture-required']});
 const page=await browser.newPage({viewport:{width:1366,height:768},deviceScaleFactor:1}); const errors=[];
 page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='warning'&& /GPU fallback|viz gpu|PulseGPU/.test(m.text()))errors.push(m.text());});
 await page.route('**/*',r=>{if(r.request().url().startsWith('http://127.0.0.1:8756'))return r.continue(); if(r.request().resourceType()==='image')return r.fulfill({contentType:'image/png',body:fs.readFileSync(root+'/logo.png')});return r.fulfill({body:'',contentType:'text/javascript'});});
 await page.addInitScript(()=>{
   const feed={shelves:[{title:'Тестовые треки',items:Array.from({length:14},(_,i)=>({kind:'song',id:String(i).padStart(11,'a'),title:'Тест переключения '+(i+1),author:'Pulse QA',dur:240,loaded:true}))}],chips:[]};
   const proxy=prefix=>new Proxy({}, {get(_t,k){return (...args)=>{
     if(String(k).startsWith('on'))return;
     if(k==='getLibrary')return Promise.resolve({settings:{look:{splash:false},perf:{showFps:false},ui:{panels:true}}});
     if(k==='list'||k==='playlists'||k==='downloads'||k==='displays')return Promise.resolve([]);
     if(k==='offlineList')return Promise.resolve({});
     if(k==='status')return Promise.resolve({am:{},sp:{}});
     if(k==='info')return Promise.resolve(null);
     if(k==='version')return Promise.resolve('1.0.0');
     if(k==='lyrics')return Promise.resolve({none:true});
     if(k==='feed')return Promise.resolve(feed);
     if(k==='next')return Promise.resolve({tracks:[]});
     if(k==='visualizerTap'){window.testTapRequest=args[0];return Promise.resolve({ok:true});}if(k==='resolve')return new Promise(()=>{});
     if(k==='prefetch')return Promise.resolve(true);
     if(k==='getGlass')return Promise.resolve({});
     return Promise.resolve({});
   };}});
   window.pulse=proxy('');for(const n of ['plugins','account','svc','ytm','spicy','discord','custom','editor','wall','accounts']) Object.defineProperty(window.pulse,n,{value:proxy(n)});
   // replace proxy with explicit nested keys (proxy getter above does not read target).
   const p=proxy('');window.pulse=new Proxy({}, {get(t,k){if(['plugins','account','svc','ytm','spicy','discord','custom','editor','wall','accounts'].includes(k))return proxy(k);return p[k];}});
   localStorage.setItem('pulse.splash','off');
 });
 await page.goto('http://127.0.0.1:8756');await page.waitForTimeout(1600);
 console.log('startup errors',errors);await page.screenshot({path:out+'/home.png'});


 const assert=require('node:assert/strict'),{installTap}=require('../visualizer-tap');
 const tone="data:audio/wav;base64,";
 await page.evaluate(async src=>{lib.queue={tracks:[{id:'qaAudioTest',title:'Аудиотест 100 Гц',author:'Pulse QA',dur:4}],idx:0};engine='audio';audioTrackId=curTrack().id;audio.src=src;audio.loop=true;E.play();openPP(true);setMode('visual');window.observedFft=0;const draw=Viz.draw;Viz.draw=function(o){if(o.freq)observedFft=Math.max(observedFft,...o.freq);return draw.call(this,o)};},tone);
 await page.waitForTimeout(1000);
 const local=await page.evaluate(()=>{const s=readSpectrum(),a=new Uint8Array(1024);return {engine,playing,state:actx.state,max:s?Math.max(...s.f):0,bass:beatState.bass,mine:PulseMR.freq(a),mineMax:Math.max(...a),visual:observedFft};});console.log('REAL local audio',local);assert.ok(local.max>50);assert.ok(local.bass>.05);assert.ok(local.mineMax>50);assert.ok(local.visual>50);
 await page.evaluate(()=>{E.pause();audio.removeAttribute('src');audio.load();closePP();});
 await page.route('https://www.youtube.com/embed/qa-analysis',r=>r.fulfill({contentType:'text/html',body:'<!doctype html><audio id="media" autoplay loop src="'+tone+'"></audio>'}));
 await page.evaluate(()=>{const el=document.getElementById('ytPlayer');const f=document.createElement('iframe');f.id='ytPlayer';f.allow='autoplay';f.src='https://www.youtube.com/embed/qa-analysis';el.replaceWith(f);openPP(true);engine='yt';playing=true;observedFft=0;});
 await page.waitForFunction(()=>window.testTapRequest&&testTapRequest.enable,{},{timeout:6000});
 const cfg=await page.evaluate(()=>({enable:true,token:testTapRequest.token,origin:location.origin}));
 const frame=page.frames().find(f=>f.url().includes('/embed/qa-analysis'));assert.ok(frame);await frame.waitForSelector('#media',{state:'attached'});await frame.evaluate(()=>document.getElementById('media').play());
 await frame.evaluate(installTap,cfg);await page.waitForFunction(()=>beatState.bass>.05 && observedFft>50,{},{timeout:20000,polling:100});
 const remote=await page.evaluate(()=>{const s=readSpectrum(),a=new Uint8Array(1024);return {diagnostics:PulseAudioSignal.diagnostics(),max:s?Math.max(...s.f):0,bass:beatState.bass,mine:PulseMR.freq(a),mineMax:Math.max(...a),visual:observedFft};});console.log('REAL cross-origin iframe audio',remote);assert.ok(remote.max>50);assert.ok(remote.bass>.05);assert.ok(remote.mineMax>50);assert.ok(remote.visual>50);
 // Text scene reads the same live bass; capture does not change original media volume.
 await page.evaluate(()=>{S().ly.vis='classic';lyStageOpen(true);});await page.waitForTimeout(400);assert.ok(await page.evaluate(()=>lys.bs>.01));assert.equal(await frame.evaluate(()=>document.getElementById('media').volume),1);
 await frame.evaluate(installTap,{...cfg,enable:false});await page.waitForTimeout(650);assert.equal(await page.evaluate(()=>readSpectrum()),null,'Stale data must not fake a live signal');assert.equal(await frame.evaluate(()=>document.getElementById('media').paused),false,'Stopping analysis must not stop playback');
 assert.deepEqual(errors,[]);console.log('Audio tests passed: real sine -> local/iframe -> visuals + bass + Mineradio.');
 await browser.close();server.close();process.exit(0);
})().catch(e=>{console.error(e);server.close();process.exit(1)});
